const items = $input.all();

function pegarCustomField(issue, id) {
  const campo = (issue.custom_fields || []).find(
    c => Number(c.id) === Number(id)
  );

  return campo?.value ?? null;
}

function numeroOuNull(valor) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return null;
  }

  const numero = Number(valor);

  return Number.isNaN(numero)
    ? null
    : numero;
}

function booleanoRedmine(valor) {
  if (
    valor === null ||
    valor === undefined ||
    valor === ''
  ) {
    return null;
  }

  return String(valor) === '1';
}

return items.map(item => {

  const issue = item.json.issue || {};
  const agile = item.json.agile_data || {};

  const sprint = pegarCustomField(issue, 18);
  const remainingStoryPoints = pegarCustomField(issue, 14);
  const planejado = pegarCustomField(issue, 24);
  const impedimento = pegarCustomField(issue, 13);

  return {
    json: {

      // ============================================
      // ISSUE
      // ============================================

      issue_id: issue.id ?? null,

      issue_subject: issue.subject ?? '',
      issue_description: issue.description ?? '',


      // ============================================
      // PROJETO
      // ============================================

      project_id: issue.project?.id ?? null,
      project_name: issue.project?.name ?? '',


      // ============================================
      // TRACKER
      // ============================================

      tracker_id: issue.tracker?.id ?? null,
      tracker_name: issue.tracker?.name ?? '',


      // ============================================
      // STATUS ATUAL
      // ============================================

      status_id: issue.status?.id ?? null,
      status_name: issue.status?.name ?? '',
      status_is_closed: issue.status?.is_closed ?? false,


      // ============================================
      // PRIORIDADE
      // ============================================

      priority_id: issue.priority?.id ?? null,
      priority_name: issue.priority?.name ?? '',


      // ============================================
      // AUTOR
      // ============================================

      author_id: issue.author?.id ?? null,
      author_name: issue.author?.name ?? '',


      // ============================================
      // RESPONSÁVEL
      // ============================================

      assigned_to_id: issue.assigned_to?.id ?? null,
      assigned_to_name: issue.assigned_to?.name ?? '',


      // ============================================
      // ISSUE PAI
      // ============================================

      parent_id: issue.parent?.id ?? null,


      // ============================================
      // DATAS
      // ============================================

      start_date: issue.start_date ?? null,
      due_date: issue.due_date ?? null,

      created_on: issue.created_on ?? null,
      updated_on: issue.updated_on ?? null,
      closed_on: issue.closed_on ?? null,


      // ============================================
      // PROGRESSO / HORAS
      // ============================================

      done_ratio: numeroOuNull(issue.done_ratio),

      estimated_hours:
        numeroOuNull(issue.estimated_hours),

      spent_hours:
        numeroOuNull(issue.spent_hours),


      // ============================================
      // AGILE
      // ============================================

      story_points:
        numeroOuNull(agile.story_points),

      remaining_story_points:
        numeroOuNull(remainingStoryPoints),

      sprint_id:
        sprint === null || sprint === ''
          ? null
          : String(sprint),

      planejado:
        booleanoRedmine(planejado),

      flag_impedimento:
        booleanoRedmine(impedimento),


      // ============================================
      // REGRA DE ENTREGA
      // ============================================

      entregue_atualmente:
        Number(issue.status?.id) === 36,


      // ============================================
      // HISTÓRICO
      // ============================================

      journals:
        issue.journals || [],

      relations:
        issue.relations || [],

      children:
        issue.children || []

    }
  };

});

const items = $input.all();

// ======================================================
// CONFIGURAÇÕES DO FRAMEWORK
// ======================================================

const STATUS_INICIO_CYCLE_TIME = 27; // Em desenvolvimento
const STATUS_ENTREGA = 36;           // Concluído
const STATUS_REABERTO = 37;          // Reaberto


// ======================================================
// FUNÇÃO PARA DIFERENÇA ENTRE DATAS
// ======================================================

function diferencaHoras(dataInicial, dataFinal) {

  if (!dataInicial || !dataFinal) {
    return null;
  }

  const inicio = new Date(dataInicial);
  const fim = new Date(dataFinal);

  const diferencaMs = fim - inicio;

  if (diferencaMs < 0) {
    return null;
  }

  return Number(
    (diferencaMs / (1000 * 60 * 60)).toFixed(2)
  );
}


// ======================================================
// PROCESSA CADA ISSUE
// ======================================================

return items.map(item => {

  const issue = item.json;

  const journals = Array.isArray(issue.journals)
    ? issue.journals
    : [];


  // ====================================================
  // GUARDA TODAS AS MUDANÇAS DE STATUS
  // ====================================================

  const mudancasStatus = [];


  for (const journal of journals) {

    const detalhes = Array.isArray(journal.details)
      ? journal.details
      : [];

    for (const detalhe of detalhes) {

      if (
        detalhe.property === 'attr' &&
        detalhe.name === 'status_id'
      ) {

        mudancasStatus.push({
          journal_id: journal.id ?? null,

          data:
            journal.created_on ?? null,

          usuario_id:
            journal.user?.id ?? null,

          usuario_nome:
            journal.user?.name ?? '',

          status_anterior:
            detalhe.old_value !== null
              ? Number(detalhe.old_value)
              : null,

          status_novo:
            detalhe.new_value !== null
              ? Number(detalhe.new_value)
              : null
        });
      }
    }
  }


  // ====================================================
  // ORDENA CRONOLOGICAMENTE
  // ====================================================

  mudancasStatus.sort((a, b) => {
    return new Date(a.data) - new Date(b.data);
  });


  // ====================================================
  // PRIMEIRA ENTRADA EM DESENVOLVIMENTO
  // ====================================================

  const entradasDesenvolvimento =
    mudancasStatus.filter(
      m => m.status_novo === STATUS_INICIO_CYCLE_TIME
    );

  const inicioCycleTime =
    entradasDesenvolvimento.length > 0
      ? entradasDesenvolvimento[0].data
      : null;


  // ====================================================
  // ENTRADAS EM CONCLUÍDO
  // ====================================================

  const entregas =
    mudancasStatus.filter(
      m => m.status_novo === STATUS_ENTREGA
    );

  const primeiraEntrega =
    entregas.length > 0
      ? entregas[0].data
      : null;

  const ultimaEntrega =
    entregas.length > 0
      ? entregas[entregas.length - 1].data
      : null;


  // ====================================================
  // REABERTURAS
  // ====================================================

  const reaberturas =
    mudancasStatus.filter(
      m => m.status_novo === STATUS_REABERTO
    );

  const quantidadeReaberturas =
    reaberturas.length;


  // ====================================================
  // LEAD TIME
  //
  // Criação → primeira entrada em Concluído
  // ====================================================

  const leadTimeHoras =
    diferencaHoras(
      issue.created_on,
      primeiraEntrega
    );


  // ====================================================
  // CYCLE TIME
  //
  // primeira entrada em desenvolvimento → entrega
  // ====================================================

  const cycleTimeHoras =
    diferencaHoras(
      inicioCycleTime,
      primeiraEntrega
    );


  // ====================================================
  // RESULTADO
  // ====================================================

  return {
    json: {

      ...issue,

      // -----------------------------------------------
      // DATAS DO FLUXO
      // -----------------------------------------------

      cycle_started_on:
        inicioCycleTime,

      first_delivered_on:
        primeiraEntrega,

      last_delivered_on:
        ultimaEntrega,


      // -----------------------------------------------
      // MÉTRICAS
      // -----------------------------------------------

      lead_time_horas:
        leadTimeHoras,

      lead_time_dias:
        leadTimeHoras === null
          ? null
          : Number((leadTimeHoras / 24).toFixed(2)),

      cycle_time_horas:
        cycleTimeHoras,

      cycle_time_dias:
        cycleTimeHoras === null
          ? null
          : Number((cycleTimeHoras / 24).toFixed(2)),


      // -----------------------------------------------
      // QUALIDADE DO FLUXO
      // -----------------------------------------------

      quantidade_reaberturas:
        quantidadeReaberturas,

      ja_foi_entregue:
        primeiraEntrega !== null,


      // -----------------------------------------------
      // HISTÓRICO NORMALIZADO DE STATUS
      // -----------------------------------------------

      status_history:
        mudancasStatus

    }
  };

});

const items = $input.all();

const saida = [];

for (const item of items) {

  const issue = item.json;

  const historico = Array.isArray(issue.status_history)
    ? issue.status_history
    : [];

  for (let i = 0; i < historico.length; i++) {

    const h = historico[i];

    saida.push({
      json: {

        // ============================================
        // IDENTIFICAÇÃO DA ISSUE
        // ============================================

        issue_id: issue.issue_id ?? null,

        project_id: issue.project_id ?? null,
        project_name: issue.project_name ?? '',

        tracker_id: issue.tracker_id ?? null,
        tracker_name: issue.tracker_name ?? '',

        sprint_id: issue.sprint_id ?? null,


        // ============================================
        // JOURNAL
        // ============================================

        journal_id: h.journal_id ?? null,

        alterado_em: h.data ?? null,

        usuario_id: h.usuario_id ?? null,
        usuario_nome: h.usuario_nome ?? '',


        // ============================================
        // STATUS
        // ============================================

        status_anterior_id:
          h.status_anterior ?? null,

        status_novo_id:
          h.status_novo ?? null,


        // ============================================
        // ORDEM DA TRANSIÇÃO
        // ============================================

        ordem_transicao: i + 1

      }
    });
  }
}

return saida;

// ======================================================
// NORMALIZAR - SPRINTS
//
// Entrada:
// retorno do endpoint /custom_fields.json
//
// Saída:
// uma linha por Sprint do custom field ID 18
// ======================================================

const items = $input.all();

// ======================================================
// 1) LOCALIZA O CUSTOM FIELD "SPRINT" - ID 18
// ======================================================

let campoSprint = null;

for (const item of items) {

  const json = item.json;

  // Caso o endpoint retorne:
  // { custom_fields: [...] }
  if (Array.isArray(json.custom_fields)) {

    campoSprint = json.custom_fields.find(
      campo => Number(campo.id) === 18
    );

    if (campoSprint) break;
  }

  // Caso o próprio item já seja o custom field
  if (Number(json.id) === 18) {
    campoSprint = json;
    break;
  }
}

// ======================================================
// 2) VALIDAÇÃO
// ======================================================

if (!campoSprint) {
  throw new Error(
    'Custom Field ID 18 - Sprint não encontrado.'
  );
}

// ======================================================
// 3) CONVERTE DD/MM/AAAA → AAAA-MM-DD
// ======================================================

function converterDataBR(data) {

  if (!data) return null;

  const partes = data.split('/');

  if (partes.length !== 3) return null;

  const [dia, mes, ano] = partes;

  return `${ano}-${mes}-${dia}`;
}

// ======================================================
// 4) TRANSFORMA POSSIBLE_VALUES EM LINHAS
// ======================================================

const saida = [];

for (const sprint of campoSprint.possible_values || []) {

  const sprintId = String(sprint.value ?? '');
  const label = String(sprint.label ?? '').trim();

  // ----------------------------------------------------
  // BACKLOG
  // ----------------------------------------------------

  const ehBacklog =
    label.toUpperCase() === 'BACKLOG';

  if (ehBacklog) {

    saida.push({
      json: {
        sprint_id: sprintId,
        sprint_nome: label,
        data_inicio: null,
        data_fim: null,
        time_nome: null,
        backlog: true
      }
    });

    continue;
  }

  // ----------------------------------------------------
  // EXTRAI AS DATAS
  //
  // Aceita:
  // 27/05/2026 à 11/06/2026
  // 06/07/2026 a 17/07/2026
  // ----------------------------------------------------

  const datas = label.match(
    /(\d{2}\/\d{2}\/\d{4})\s+[aà]\s+(\d{2}\/\d{2}\/\d{4})/i
  );

  const dataInicio =
    datas ? converterDataBR(datas[1]) : null;

  const dataFim =
    datas ? converterDataBR(datas[2]) : null;

  // ----------------------------------------------------
  // EXTRAI O TIME ENTRE PARÊNTESES
  //
  // Ex.:
  // (...) (GEDS)
  // (...) (CATES)
  // ----------------------------------------------------

  const timeMatch = label.match(
    /\(([^()]+)\)\s*$/
  );

  const timeNome =
    timeMatch
      ? timeMatch[1].trim()
      : null;

  // ----------------------------------------------------
  // SAÍDA
  // ----------------------------------------------------

  saida.push({
    json: {
      sprint_id: sprintId,
      sprint_nome: label,
      data_inicio: dataInicio,
      data_fim: dataFim,
      time_nome: timeNome,
      backlog: false
    }
  });
}

return saida;

const itemsHtml = $input.all();

const itemsPostgres =
  $('POSTGRES - SPRINTS HISTÓRICAS FALTANTES').all();

function limparHtml(valor) {
  return String(valor ?? '')
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&agrave;/gi, 'à')
    .replace(/&aacute;/gi, 'á')
    .replace(/&Agrave;/gi, 'À')
    .replace(/\s+/g, ' ')
    .trim();
}

function converterDataBR(data) {
  if (!data) return null;

  const partes = data.split('/');

  if (partes.length !== 3) {
    return null;
  }

  const [dia, mes, ano] = partes;

  return `${ano}-${mes}-${dia}`;
}

return itemsHtml.map((item, index) => {

  const html = String(item.json.data ?? '');

  const origem =
    itemsPostgres[index]?.json ?? {};

  // ==========================================
  // LOCALIZA O CAMPO SPRINT - CF 18
  // ==========================================

  const matchSprint = html.match(
    /<div class="enumeration_cf cf_18 attribute">[\s\S]*?<span>Sprint<\/span>:[\s\S]*?<div class="value">([\s\S]*?)<\/div>/i
  );

  const sprintNome = matchSprint
    ? limparHtml(matchSprint[1])
    : null;

  // ==========================================
  // EXTRAI AS DATAS DO NOME DA SPRINT
  // ==========================================

  const matchDatas = sprintNome
    ? sprintNome.match(
        /(\d{2}\/\d{2}\/\d{4})\s+(?:a|à)\s+(\d{2}\/\d{2}\/\d{4})/i
      )
    : null;

  const dataInicio =
    matchDatas
      ? converterDataBR(matchDatas[1])
      : null;

  const dataFim =
    matchDatas
      ? converterDataBR(matchDatas[2])
      : null;

  // ==========================================
  // EXTRAI O TIME QUANDO EXISTIR
  // Ex.: (... GEDS), (... CATES)
  // ==========================================

  const matchTime = sprintNome
    ? sprintNome.match(/\(([^()]+)\)\s*$/)
    : null;

  const timeNome =
    matchTime
      ? matchTime[1].trim()
      : null;

  return {
    json: {
      sprint_id:
        origem.sprint_id ?? null,

      issue_id:
        origem.issue_id ?? null,

      sprint_nome:
        sprintNome,

      data_inicio:
        dataInicio,

      data_fim:
        dataFim,

      time_nome:
        timeNome,

      backlog: false
    }
  };

});

const items = $input.all();

const saida = [];

for (const item of items) {

  const issue = item.json;

  const journals = Array.isArray(issue.journals)
    ? issue.journals
    : [];

  for (const journal of journals) {

    const detalhes = Array.isArray(journal.details)
      ? journal.details
      : [];

    for (const detalhe of detalhes) {

      // ==========================================
      // CAMPO PERSONALIZADO 18 = SPRINT
      // ==========================================

      if (
        detalhe.property === 'cf' &&
        String(detalhe.name) === '18'
      ) {

        saida.push({
          json: {

            issue_id:
              issue.issue_id ?? null,

            project_id:
              issue.project_id ?? null,

            project_name:
              issue.project_name ?? '',

            journal_id:
              journal.id ?? null,

            alterado_em:
              journal.created_on ?? null,

            usuario_id:
              journal.user?.id ?? null,

            usuario_nome:
              journal.user?.name ?? '',

            sprint_anterior_id:
              detalhe.old_value === null ||
              detalhe.old_value === ''
                ? null
                : String(detalhe.old_value),

            sprint_nova_id:
              detalhe.new_value === null ||
              detalhe.new_value === ''
                ? null
                : String(detalhe.new_value)
          }
        });

      }
    }
  }
}

return saida;
